  UNION ALL SELECT 'pol.agent_posts_public_read.shape' AS name, coalesce((SELECT p.cmd || '|' || array_to_string(p.roles, ',') || '|' || p.permissive FROM pg_policies p WHERE p.schemaname = 'storage' AND p.tablename = 'objects' AND p.policyname = 'agent_posts_public_read'), 'ABSENT') AS actual
  UNION ALL SELECT 'pol.agent_posts_public_read.norm' AS name, coalesce((SELECT regexp_replace(coalesce(p.qual,'') || '~' || coalesce(p.with_check,''), '[\s()]|::text', '', 'g') FROM pg_policies p WHERE p.schemaname = 'storage' AND p.tablename = 'objects' AND p.policyname = 'agent_posts_public_read'), 'ABSENT') AS actual
  UNION ALL SELECT 'pol.chat_images_public_read.norm' AS name, coalesce((SELECT regexp_replace(coalesce(p.qual,'') || '~' || coalesce(p.with_check,''), '[\s()]|::text', '', 'g') FROM pg_policies p WHERE p.schemaname = 'storage' AND p.tablename = 'objects' AND p.policyname = 'chat images public read'), 'ABSENT') AS actual
  UNION ALL SELECT 'pol.playlist_public_read.norm' AS name, coalesce((SELECT regexp_replace(coalesce(p.qual,'') || '~' || coalesce(p.with_check,''), '[\s()]|::text', '', 'g') FROM pg_policies p WHERE p.schemaname = 'storage' AND p.tablename = 'objects' AND p.policyname = 'playlist covers are publicly readable'), 'ABSENT') AS actual
  UNION ALL SELECT 'pol.vs_media_read.norm' AS name, coalesce((SELECT regexp_replace(coalesce(p.qual,'') || '~' || coalesce(p.with_check,''), '[\s()]|::text', '', 'g') FROM pg_policies p WHERE p.schemaname = 'storage' AND p.tablename = 'objects' AND p.policyname = 'vs_media_read'), 'ABSENT') AS actual
  UNION ALL SELECT 'pol.chat_images_public_read.shape' AS name, coalesce((SELECT p.cmd || '|' || array_to_string(p.roles, ',') || '|' || p.permissive FROM pg_policies p WHERE p.schemaname = 'storage' AND p.tablename = 'objects' AND p.policyname = 'chat images public read'), 'ABSENT') AS actual
  UNION ALL SELECT 'pol.playlist_public_read.shape' AS name, coalesce((SELECT p.cmd || '|' || array_to_string(p.roles, ',') || '|' || p.permissive FROM pg_policies p WHERE p.schemaname = 'storage' AND p.tablename = 'objects' AND p.policyname = 'playlist covers are publicly readable'), 'ABSENT') AS actual
  UNION ALL SELECT 'pol.vs_media_read.shape' AS name, coalesce((SELECT p.cmd || '|' || array_to_string(p.roles, ',') || '|' || p.permissive FROM pg_policies p WHERE p.schemaname = 'storage' AND p.tablename = 'objects' AND p.policyname = 'vs_media_read'), 'ABSENT') AS actual
  UNION ALL SELECT 'pol.chat_images_auth_upload.shape' AS name, coalesce((SELECT p.cmd || '|' || array_to_string(p.roles, ',') || '|' || p.permissive FROM pg_policies p WHERE p.schemaname = 'storage' AND p.tablename = 'objects' AND p.policyname = 'chat images auth upload'), 'ABSENT') AS actual
  UNION ALL SELECT 'ins.vs-entries' AS name, coalesce((SELECT coalesce(string_agg(p.policyname::text, ',' ORDER BY p.policyname::text COLLATE "C"),'(none)') FROM pg_policies p WHERE p.schemaname = 'storage' AND p.tablename = 'objects' AND p.cmd IN ('INSERT','ALL') AND (coalesce(p.qual,'') || ' ' || coalesce(p.with_check,'')) ~ 'vs-entries'), 'ABSENT') AS actual
), e(name, expected, accepted) AS (VALUES
  ('sel.agent-posts', 'agent_posts_public_read', ARRAY['agent_posts_public_read']::text[]),
  ('sel.chat-images', 'chat images public read', ARRAY['chat images public read']::text[]),
  ('sel.playlist-covers', 'playlist covers are publicly readable', ARRAY['playlist covers are publicly readable']::text[]),
  ('sel.vs-entries', 'vs_media_read', ARRAY['vs_media_read']::text[]),
  ('pol.agent_posts_public_read.shape', 'SELECT|public|PERMISSIVE', ARRAY['SELECT|public|PERMISSIVE']::text[]),
  ('pol.agent_posts_public_read.norm', 'bucket_id=''agent-posts''~', ARRAY['bucket_id=''agent-posts''~']::text[]),
  ('pol.chat_images_public_read.norm', 'bucket_id=''chat-images''~', ARRAY['bucket_id=''chat-images''~']::text[]),
  ('pol.playlist_public_read.norm', 'bucket_id=''playlist-covers''~', ARRAY['bucket_id=''playlist-covers''~']::text[]),
  ('pol.vs_media_read.norm', 'bucket_id=''vs-entries''~', ARRAY['bucket_id=''vs-entries''~']::text[]),
  ('pol.chat_images_public_read.shape', 'SELECT|public|PERMISSIVE', ARRAY['SELECT|public|PERMISSIVE']::text[]),
  ('pol.playlist_public_read.shape', 'SELECT|public|PERMISSIVE', ARRAY['SELECT|public|PERMISSIVE']::text[]),
  ('pol.vs_media_read.shape', 'SELECT|public|PERMISSIVE', ARRAY['SELECT|public|PERMISSIVE']::text[]),
  ('pol.chat_images_auth_upload.shape', 'INSERT|authenticated|PERMISSIVE', ARRAY['INSERT|authenticated|PERMISSIVE']::text[]),
  ('ins.vs-entries', 'vs_media_insert', ARRAY['vs_media_insert']::text[])
), r AS (SELECT e.name, coalesce(e.expected, 'RECORD ONLY') AS expected, a.actual, (e.accepted IS NULL OR a.actual = ANY (e.accepted)) AS ok FROM e LEFT JOIN a USING (name))
SELECT '000_ALL_OK' AS name, 'PRE' AS expected, 'PRE' AS actual, bool_and(ok) AS ok FROM r
UNION ALL SELECT name, expected, actual, ok FROM r
ORDER BY 1;
COMMIT;
